pub const QueryFilters = struct {
    pub const opcode: u8 = 29;
    pub const extension = current_mod.extension;

    drawable: xproto.Drawable,

    pub fn encode(self: *const @This(), writer: *std.Io.Writer) !void {
        try writer.writeInt(u32, self.drawable.toInt(), .native);
    }

    pub const Reply = struct {
        aliases: []const u16,
        decoded_aliases_buf: ?[]u16 = null,
        filters: []const xproto.STR,
        decoded_filters_buf: ?[]xproto.STR = null,

        pub fn decode(allocator: std.mem.Allocator, reader: *std.Io.Reader, header_: wire.ReplyHeader) !@This() {
            var result: @This() = undefined;
            _ = header_;
            const num_aliases = try reader.takeInt(u32, .native);
            const num_filters = try reader.takeInt(u32, .native);
            _ = try reader.take(16);
            const decoded_aliases_buf = try allocator.alloc(u16, @intCast(num_aliases));
            for (decoded_aliases_buf) |*elem| {
                elem.* = try reader.takeInt(u16, .native);
            }
            result.aliases = decoded_aliases_buf;
            result.decoded_aliases_buf = decoded_aliases_buf;
            const decoded_filters_buf = try allocator.alloc(xproto.STR, @intCast(num_filters));
            for (decoded_filters_buf) |*elem| {
                elem.* = try xproto.STR.decode(allocator, reader);
            }
            result.filters = decoded_filters_buf;
            result.decoded_filters_buf = decoded_filters_buf;
            return result;
        }

        pub fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.decoded_aliases_buf) |buf| {
                allocator.free(buf);
                self.decoded_aliases_buf = null;
                self.aliases = &.{};
            }
            if (self.decoded_filters_buf) |buf| {
                for (buf) |*it| {
                    it.deinit(allocator);
                }
                allocator.free(buf);
                self.decoded_filters_buf = null;
                self.filters = &.{};
            }
        }
    };
};

